-- =============================================================================
-- MyBand.video - 01 core schema
-- =============================================================================
--
-- Seven tables for the music intelligence pipeline: profiles, projects, songs,
-- uploads, analysis_jobs, analysis_results, storage_gc_queue.
--
-- Rules that hold for every table in this schema:
--
--   * Primary keys are UUIDv7 generated by the application
--     (apps/api/app/core/ids.py). There is no `default gen_random_uuid()`
--     anywhere. A v4 key scatters b-tree inserts across the whole index; a v7
--     key is time ordered, so inserts land in the rightmost page and stay
--     cache-resident. The cost is that every INSERT carries an id, which the
--     API always has.
--   * `timestamptz`, never `timestamp`: GPU workers in other regions write to
--     these rows and every instant has to carry an offset.
--   * Enumerations are text + CHECK rather than a Postgres enum type. Adding a
--     value to an enum needs ALTER TYPE ... ADD VALUE, which cannot run in
--     every transaction context; a CHECK is a one line migration.
--   * Soft deletes: `deleted_at` marks a row as gone and nothing in the API
--     issues DELETE, so read policies end with `deleted_at is null`.
--   * Ownership columns reference auth.users(id) ON DELETE CASCADE: closing an
--     account removes its data without an application cleanup job.
--   * Every foreign key has an index (see docs/schema.md, "Cascade indexes") -
--     without one, deleting a single user sequentially scans every child table.
--   * `updated_at` is maintained by the set_updated_at() trigger (migration 02).
--
-- Creation order follows the foreign keys. `songs.latest_job_id` points back at
-- `analysis_jobs.id`, so that single edge is added at the end of this file.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- profiles: the application-side view of an auth.users row
-- -----------------------------------------------------------------------------
create table public.profiles (
    id           uuid primary key references auth.users (id) on delete cascade,
    email        text,
    display_name text,
    avatar_url   text,
    plan         text not null default 'free',
    created_at   timestamptz not null default now(),
    updated_at   timestamptz not null default now(),
    deleted_at   timestamptz,
    constraint profiles_plan_check
        check (plan in ('free', 'pro')),
    constraint profiles_email_check
        check (email is null or char_length(email) between 3 and 320),
    constraint profiles_display_name_check
        check (display_name is null or char_length(display_name) between 1 and 60),
    constraint profiles_avatar_url_check
        check (avatar_url is null
               or (avatar_url like 'https://%' and char_length(avatar_url) between 9 and 2048))
);

comment on table public.profiles is
    'One row per auth.users row, created by the on_auth_user_created trigger. '
    '`id` has no default: it *is* the auth.users primary key.';
comment on column public.profiles.plan is
    'Subscription tier. Billing tables are deliberately deferred - usage is '
    'metered from analysis_jobs rows that reached status = succeeded.';

-- -----------------------------------------------------------------------------
-- projects: a user-owned grouping of songs (album, set list, client)
-- -----------------------------------------------------------------------------
create table public.projects (
    id         uuid primary key,
    owner_id   uuid not null references auth.users (id) on delete cascade,
    name       text not null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    deleted_at timestamptz,
    constraint projects_name_check
        check (char_length(name) between 1 and 120)
);

comment on table public.projects is
    'User-owned grouping of songs. Soft deleted by the app; a hard delete '
    'unfiles its songs instead of destroying them (songs.project_id is '
    'ON DELETE SET NULL).';

-- Deliberately not partial on `deleted_at is null`: the ON DELETE CASCADE
-- lookup runs `owner_id = $1`, which does not imply that predicate, so a partial
-- index could never be used and every account deletion would scan the table.
-- The trailing created_at desc still serves "my projects, newest first".
create index projects_owner_id_created_at_idx
    on public.projects (owner_id, created_at desc);

-- -----------------------------------------------------------------------------
-- songs: one uploaded recording; the anchor of the analysis pipeline
-- -----------------------------------------------------------------------------
create table public.songs (
    id                  uuid primary key,
    user_id             uuid not null references auth.users (id) on delete cascade,
    project_id          uuid references public.projects (id) on delete set null,
    latest_job_id       uuid,  -- analysed at the end of this file
    title               text not null,
    artist              text,
    duration_ms         integer,
    source_object_key   text not null,
    source_checksum     text,
    source_bytes        bigint,
    source_content_type text,
    created_at          timestamptz not null default now(),
    updated_at          timestamptz not null default now(),
    deleted_at          timestamptz,
    constraint songs_title_check
        check (char_length(title) between 1 and 200),
    constraint songs_artist_check
        check (artist is null or char_length(artist) between 1 and 200),
    constraint songs_duration_ms_check
        check (duration_ms is null or duration_ms between 0 and 21600000),
    constraint songs_source_bytes_check
        check (source_bytes is null or source_bytes > 0),
    constraint songs_source_checksum_check
        check (source_checksum is null or source_checksum ~ '^[0-9a-f]{64}$'),
    -- Object keys are immutable and always owner scoped. The API derives every
    -- key from the authenticated user, so the database asserts the same shape:
    -- users/<user uuid>/uploads/<upload uuid>/<filename>
    -- The length bound is a separate CHECK because Postgres' regex engine caps
    -- repetition counts at 255 (RE_DUP_MAX), so `{1,512}` is not expressible.
    constraint songs_source_object_key_check
        check (source_object_key ~ '^users/[0-9a-fA-F-]{36}/[A-Za-z0-9._/-]+$'
               and char_length(source_object_key) <= 512)
);

comment on table public.songs is
    'One uploaded recording. `source_object_key` is the raw audio in R2 and is '
    'never rewritten; artifacts live under analysis_results.object_key.';
comment on column public.songs.latest_job_id is
    'Pointer to the newest analysis_jobs row for this song, maintained by the '
    'queue service. Denormalised so the library list needs no aggregate.';

create index songs_user_id_created_at_idx on public.songs (user_id, created_at desc);
-- project_id is a cascade edge (ON DELETE SET NULL), so it needs its own index
-- even though the app also filters by user_id.
create index songs_project_id_idx on public.songs (project_id);
create index songs_latest_job_id_idx on public.songs (latest_job_id);

-- -----------------------------------------------------------------------------
-- analysis_jobs: one attempt at analysing one song
-- -----------------------------------------------------------------------------
-- The queue seam. `status` is the whole protocol: queued -> dispatched ->
-- running -> succeeded | failed | canceled. A retry is a new row, never a
-- resurrected one, which is what makes billing countable (one billable unit is
-- one row reaching succeeded).
create table public.analysis_jobs (
    id                 uuid primary key,
    user_id            uuid not null references auth.users (id) on delete cascade,
    song_id            uuid not null references public.songs (id) on delete cascade,
    status             text not null default 'queued',
    pipeline_version   text not null,
    source_object_key  text not null,
    source_checksum    text,
    attempts           smallint not null default 0,
    compute_seconds    numeric(10, 3),
    runpod_job_id      text,
    error_code         text,
    error_message      text,
    dispatched_at      timestamptz,
    started_at         timestamptz,
    finished_at        timestamptz,
    heartbeat_at       timestamptz,
    created_at         timestamptz not null default now(),
    updated_at         timestamptz not null default now(),
    deleted_at         timestamptz,
    constraint analysis_jobs_status_check
        check (status in ('queued', 'dispatched', 'running',
                          'succeeded', 'failed', 'canceled')),
    constraint analysis_jobs_attempts_check
        check (attempts between 0 and 100),
    constraint analysis_jobs_compute_seconds_check
        check (compute_seconds is null or compute_seconds >= 0),
    constraint analysis_jobs_pipeline_version_check
        check (char_length(pipeline_version) between 1 and 64),
    constraint analysis_jobs_runpod_job_id_check
        check (runpod_job_id is null or char_length(runpod_job_id) between 1 and 128),
    constraint analysis_jobs_error_code_check
        check (error_code is null or char_length(error_code) between 1 and 64),
    constraint analysis_jobs_error_message_check
        check (error_message is null or char_length(error_message) between 1 and 2000),
    constraint analysis_jobs_source_object_key_check
        check (source_object_key ~ '^users/[0-9a-fA-F-]{36}/[A-Za-z0-9._/-]+$'
               and char_length(source_object_key) <= 512),
    constraint analysis_jobs_source_checksum_check
        check (source_checksum is null or source_checksum ~ '^[0-9a-f]{64}$'),
    -- Billing/analytics invariant: a terminal job carries a finish time and a
    -- non-terminal job does not.
    constraint analysis_jobs_finished_at_check
        check ((status in ('succeeded', 'failed', 'canceled')) = (finished_at is not null)),
    -- A failure always names a reason...
    constraint analysis_jobs_failure_reason_check
        check (status <> 'failed' or error_code is not null),
    -- ...and a reason only ever exists on a job that did not succeed.
    constraint analysis_jobs_error_code_terminal_check
        check (error_code is null or status in ('failed', 'canceled')),
    -- Identity for analysis_results: a result may only be attached to a job that
    -- belongs to the same user (composite FK below).
    constraint analysis_jobs_id_user_id_key unique (id, user_id)
);

-- -----------------------------------------------------------------------------
-- uploads: lifecycle of one object in R2 (the browser uploads straight to R2)
-- -----------------------------------------------------------------------------
create table public.uploads (
    id                    uuid primary key,
    user_id               uuid not null references auth.users (id) on delete cascade,
    song_id               uuid references public.songs (id) on delete cascade,
    object_key            text not null,
    status                text not null default 'pending',
    declared_bytes        bigint,
    declared_content_type text,
    checksum_expected     text,
    bytes_actual          bigint,
    content_type_actual   text,
    checksum_actual       text,
    etag_actual           text,
    multipart_upload_id   text,
    expires_at            timestamptz not null,
    completed_at          timestamptz,
    created_at            timestamptz not null default now(),
    updated_at            timestamptz not null default now(),
    constraint uploads_object_key_key unique (object_key),
    constraint uploads_status_check
        check (status in ('pending', 'completed', 'aborted', 'expired')),
    constraint uploads_object_key_check
        check (object_key ~ '^users/[0-9a-fA-F-]{36}/[A-Za-z0-9._/-]+$'
               and char_length(object_key) <= 512),
    constraint uploads_declared_bytes_check
        check (declared_bytes is null or declared_bytes > 0),
    constraint uploads_bytes_actual_check
        check (bytes_actual is null or bytes_actual > 0),
    constraint uploads_declared_content_type_check
        check (declared_content_type is null
               or char_length(declared_content_type) between 3 and 128),
    constraint uploads_content_type_actual_check
        check (content_type_actual is null
               or char_length(content_type_actual) between 3 and 128),
    constraint uploads_checksum_expected_check
        check (checksum_expected is null or checksum_expected ~ '^[0-9a-f]{64}$'),
    constraint uploads_checksum_actual_check
        check (checksum_actual is null or checksum_actual ~ '^[0-9a-f]{64}$'),
    constraint uploads_etag_check
        check (etag_actual is null or char_length(etag_actual) between 1 and 128),
    constraint uploads_multipart_upload_id_check
        check (multipart_upload_id is null
               or char_length(multipart_upload_id) between 1 and 256),
    -- A completed upload records what actually landed in the bucket, so a song is
    -- never built on a size the API did not confirm. The sha256 stays optional:
    -- S3 exposes only an ETag (etag_actual), and a client that sends no
    -- x-amz-checksum-sha256 leaves us without one.
    constraint uploads_completed_check
        check (status <> 'completed'
               or (bytes_actual is not null and completed_at is not null))
);

comment on table public.uploads is
    'One row per object the browser is allowed to PUT. Claimed by exactly one '
    'song; pending rows past expires_at are swept and their multipart upload is '
    'aborted through storage_gc_queue.';

-- At most one claimed upload per song. This partial index is safe for the
-- ON DELETE CASCADE lookup because `song_id = $1` implies `song_id is not null`,
-- so it doubles as the cascade index - see projects.owner_id for the counter
-- example where that implication does not hold.
create unique index uploads_claim_key on public.uploads (song_id) where song_id is not null;

create index uploads_user_id_created_at_idx on public.uploads (user_id, created_at desc);

-- Sweeps abandoned direct-to-R2 uploads: `status = 'pending' and
-- expires_at < now()`. expires_at is not a cascade edge, so partial is safe.
create index uploads_pending_expires_at_idx
    on public.uploads (expires_at) where status = 'pending';

-- -----------------------------------------------------------------------------
-- analysis_jobs indexes: the queue seam, the cascade edges and the usage meter
-- -----------------------------------------------------------------------------
-- Cascade edges first: both are plain indexes on purpose (a partial index would
-- be skipped by the RI trigger and turn account deletion into a seq scan).
create index analysis_jobs_song_id_created_at_idx
    on public.analysis_jobs (song_id, created_at desc);
create index analysis_jobs_user_id_created_at_idx
    on public.analysis_jobs (user_id, created_at desc);

-- RunPod calls back with the worker's job id, not ours.
create index analysis_jobs_runpod_job_id_idx
    on public.analysis_jobs (runpod_job_id) where runpod_job_id is not null;

-- The claim path: `where status in (queued, dispatched, running) order by
-- created_at` returns the oldest work first, and the same index answers "how
-- deep is the queue" and gives the reaper its scan (the active set is bounded by
-- worker concurrency, so a reaper looking for a stale heartbeat_at does not need
-- an index of its own - which keeps heartbeat_at updates HOT).
create index analysis_jobs_active_created_at_idx
    on public.analysis_jobs (created_at)
    where status in ('queued', 'dispatched', 'running');

-- One job in flight per song. Unique, so a double click cannot start two
-- analyses; partial on status, so it is not usable for the song_id cascade
-- lookup above (which is why that plain index has to exist as well).
create unique index analysis_jobs_one_active_per_song_key
    on public.analysis_jobs (song_id)
    where status in ('queued', 'dispatched', 'running');

-- The usage meter. Partial rather than a plain (user_id, finished_at) index
-- because failed and canceled jobs are never billable, and this is the hottest
-- reporting query in the product: "billable job for user X in period Y".
create index analysis_jobs_usage_idx
    on public.analysis_jobs (user_id, finished_at) where status = 'succeeded';

-- -----------------------------------------------------------------------------
-- analysis_results: one row per artifact kind produced by a job
-- -----------------------------------------------------------------------------
-- Small payloads (BPM, key, a chord progression, the section list) live inline in
-- `summary`; anything large (a MIDI file, a beat grid, a per-frame chord
-- timeline) goes to R2 and is referenced by `object_key`. `payload_bytes` is the
-- writer's own measurement of the serialised `summary` and is capped here -
-- pg_column_size() is not immutable, so the API measures and the database
-- enforces the limit it was handed.
create table public.analysis_results (
    id                  uuid primary key,
    job_id              uuid not null,
    user_id             uuid not null,
    kind                text not null,
    summary             jsonb not null default '{}'::jsonb,
    payload_bytes       integer not null default 0,
    object_key          text,
    object_bytes        bigint,
    object_content_type text,
    created_at          timestamptz not null default now(),
    updated_at          timestamptz not null default now(),
    constraint analysis_results_job_kind_key unique (job_id, kind),
    -- Composite, not job_id alone: a result may only hang off a job that belongs
    -- to the same user, so it can never be attributed to another account - which
    -- is what the select policy and the storage accounting rely on. The API
    -- satisfies it with `insert ... select id, user_id from analysis_jobs ...`.
    -- There is no separate auth.users foreign key: deleting a user cascades to
    -- analysis_jobs, which cascades to here.
    constraint analysis_results_job_user_fkey
        foreign key (job_id, user_id)
        references public.analysis_jobs (id, user_id) on delete cascade,
    constraint analysis_results_kind_check
        check (kind in ('bpm', 'key', 'chords', 'midi', 'sections')),
    constraint analysis_results_summary_object_check
        check (jsonb_typeof(summary) = 'object'),
    constraint analysis_results_payload_bytes_check
        check (payload_bytes between 0 and 8192),
    constraint analysis_results_object_key_check
        check (object_key ~ '^users/[0-9a-fA-F-]{36}/[A-Za-z0-9._/-]+$'
               and char_length(object_key) <= 512),
    constraint analysis_results_object_bytes_check
        check (object_bytes is null or object_bytes > 0),
    constraint analysis_results_object_content_type_check
        check (object_content_type is null
               or char_length(object_content_type) between 3 and 128),
    -- An artifact in R2 without its size, or a size without the key, is a bug.
    constraint analysis_results_object_check
        check ((object_key is null) = (object_bytes is null))
);

comment on table public.analysis_results is
    'Artifacts of one job, one row per kind. `summary` holds the small inline '
    'digest (<= 8192 bytes, capped in the API), `object_key` the R2 object that '
    'holds the full payload. The (job_id, kind) key is what makes re-running a '
    'pipeline idempotent: the writer upserts on it.';

-- The only index beyond the (job_id, kind) key: per-user storage accounting
-- (`select sum(object_bytes) ... group by user_id`) and RLS-filtered reads.
-- Artifacts are otherwise fetched through their job, whose index covers that.
create index analysis_results_user_id_idx on public.analysis_results (user_id);

-- -----------------------------------------------------------------------------
-- storage_gc_queue: objects R2 is still owed a delete for
-- -----------------------------------------------------------------------------
-- Deleting a row must never be what makes a bucket call: the transaction that
-- soft deletes a song enqueues an entry here and a worker drains it, so a failed
-- S3 call cannot roll back a user action. `user_id` is ON DELETE SET NULL rather
-- than CASCADE on purpose - closing an account is exactly the moment those
-- objects must be removed, so the row has to survive the user.
create table public.storage_gc_queue (
    id                  uuid primary key,
    user_id             uuid references auth.users (id) on delete set null,
    object_key          text not null,
    operation           text not null default 'delete_object',
    multipart_upload_id text,
    reason              text not null,
    attempts            smallint not null default 0,
    last_error          text,
    enqueued_at         timestamptz not null default now(),
    next_attempt_at     timestamptz not null default now(),
    claimed_at          timestamptz,
    completed_at        timestamptz,
    constraint storage_gc_queue_object_key_key unique (object_key),
    constraint storage_gc_queue_operation_check
        check (operation in ('delete_object', 'abort_multipart', 'delete_prefix')),
    constraint storage_gc_queue_reason_check
        check (reason in ('song_deleted', 'project_deleted', 'result_replaced',
                          'upload_aborted', 'upload_expired', 'manual')),
    constraint storage_gc_queue_attempts_check
        check (attempts between 0 and 100),
    constraint storage_gc_queue_object_key_check
        check (object_key ~ '^users/[0-9a-fA-F-]{36}/[A-Za-z0-9._/-]+$'
               and char_length(object_key) <= 512),
    constraint storage_gc_queue_last_error_check
        check (last_error is null or char_length(last_error) between 1 and 1000),
    -- The upload id is meaningful only for AbortMultipartUpload, and required by it.
    constraint storage_gc_queue_multipart_check
        check ((operation = 'abort_multipart') = (multipart_upload_id is not null))
);

comment on table public.storage_gc_queue is
    'One row per R2 object that is owed a delete or a multipart abort. Enqueued '
    'in the same transaction that removes the owning row, drained by a worker. '
    'unique(object_key) makes re-enqueueing idempotent: the writer reopens a '
    'finished row instead of inserting a second one.';

-- The drain path: `where completed_at is null and next_attempt_at <= now()
-- order by next_attempt_at`. Partial is safe because next_attempt_at is not a
-- cascade edge - contrast the plain index on user_id below, which exists for the
-- ON DELETE SET NULL lookup against auth.users.
create index storage_gc_queue_due_idx
    on public.storage_gc_queue (next_attempt_at) where completed_at is null;
create index storage_gc_queue_user_id_idx on public.storage_gc_queue (user_id);

-- -----------------------------------------------------------------------------
-- The one circular foreign key
-- -----------------------------------------------------------------------------
-- songs.latest_job_id -> analysis_jobs.id cannot be declared inline, because
-- analysis_jobs.song_id already points the other way. It is nullable, so the
-- cycle is only closed by an UPDATE once both rows exist:
-- insert song -> insert job -> `update songs set latest_job_id = job.id`.
-- ON DELETE SET NULL keeps the pair safe in both directions.
alter table public.songs
    add constraint songs_latest_job_id_fkey
    foreign key (latest_job_id) references public.analysis_jobs (id) on delete set null;






